-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: update only genuinely empty published lessons; add each origin/type once.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":1,"skill":"الكلام المفيد وأقسام الكلمة","passage":"الكلام في اصطلاح النحو قول يفيد معنى يحسن السكوت عليه، مثل «نجحَ الطالبُ»، ويتكون من كلمات أسماء وأفعال وحروف. أما «إذا حضرَ» وحدها فلا تعطي في السياق المعتاد جملة مكتملة المعنى، مع إمكان تمام الكلام بقرائن الحوار.","prompt":"أي تركيب تام المعنى في المثال؟","correct":"نجح الطالب","w1":"إذا حضر","w2":"من فوق","w3":"في وقت","practice":"اكتب خمس جمل مفيدة، ثم صنف كلماتها إلى اسم وفعل وحرف، وفسر وجه الإفادة."},{"n":2,"skill":"علامات الاسم والفعل والحرف","passage":"يُعرف الاسم بقبول بعض علامات مثل «أل» أو التنوين أو الجر في أمثلة مناسبة، ويُعرف الفعل بقبول «قد» للفعل في سياقاتها، والحرف لا يقبل علامات الاسم والفعل نفسها. لا يلزم اجتماع جميع العلامات في كل لفظ.","prompt":"أي كلمة تقبل أل التعريف؟","correct":"كتاب","w1":"كتبَ","w2":"إلى","w3":"لن","practice":"صنف خمسة عشر لفظًا إلى اسم وفعل وحرف، واذكر علامة مناسبة لكل نوع دون تطبيق علامة لا تقبلها الكلمة."},{"n":3,"skill":"مفهوم علم التصريف","passage":"يدرس الصرف بنية الكلمة وما يطرأ عليها من تغيير مثل الانتقال من «كتب» إلى «كاتب» و«مكتوب»، في حين يبحث النحو غالبًا في وظائف الكلمات وعلاماتها في التركيب. يكمل المجالان أحدهما الآخر في تحليل الجملة.","prompt":"ما المثال الدال على تغير بنية الكلمة؟","correct":"كتب إلى كاتب","w1":"قرأتُ الكتابَ","w2":"في المكتبة","w3":"هذا كتاب","practice":"اكتب جذور خمسة أفعال ومشتقين من كل جذر، ثم بيّن الفرق بين التحليل الصرفي والنحوي."},{"n":4,"skill":"الفعل المجرد والمزيد","passage":"«علم» ثلاثي مجرد حروفه أصلية، و«علّم» زيد بالتضعيف ويُوزن «فعّل». لا يصح اعتبار كل حرف في الفعل الطويل أصليًا؛ يحتاج التحليل الرجوع إلى الجذر والوزن والمعنى.","prompt":"ما نوع الفعل «علّم» بالنسبة إلى «علم»؟","correct":"ثلاثي مزيد بالتضعيف","w1":"ثلاثي مجرد","w2":"رباعي مجرد","w3":"اسم فاعل","practice":"صنف عشرة أفعال إلى مجرد ومزيد، ثم حدد الجذر والوزن وحروف الزيادة."},{"n":5,"skill":"علوم البلاغة الثلاثة","passage":"تتفرع البلاغة العربية في التقسيم الدراسي الشائع إلى علم المعاني الذي يراعي مقتضى الحال، والبيان الذي يعالج التشبيه والمجاز والكناية، والبديع الذي يدرس وجوه التحسين مثل الطباق والجناس. تتداخل الوظائف في الخطاب الحقيقي.","prompt":"أي علم يدرس التشبيه والاستعارة أساسًا؟","correct":"علم البيان","w1":"علم العروض","w2":"علم النحو","w3":"علم القافية","practice":"أنشئ بطاقة مقارنة لعلوم البلاغة الثلاثة مع مثال أصلي لكل علم وأثره."},{"n":6,"skill":"علم المعاني ومقتضى الحال","passage":"في مخاطبة طالب يعرف المعلومة يمكن الاكتفاء بخبر مباشر، وفي مقام الشك قد يحتاج المتكلم إلى توكيد مناسب مثل «إنَّ المشروعَ جاهزٌ». ملاءمة الجملة للمخاطب والغرض من قضايا علم المعاني، لا مجرد زيادة كلمات التوكيد.","prompt":"متى يكون توكيد الخبر أكثر مناسبة؟","correct":"عند وجود شك عند المخاطب","w1":"عندما لا يوجد مخاطب دائمًا","w2":"في كل جملة بلا تمييز","w3":"بعد كل حرف جر","practice":"اكتب خبرًا لثلاثة مخاطبين مختلفين من حيث العلم والشك والإنكار، ثم اختر درجة التوكيد وعلل."},{"n":7,"skill":"المعرب والمبني","passage":"«هذا» اسم إشارة مبني على السكون في محل رفع مبتدأ في «هذا كتابٌ»، و«كتابٌ» اسم معرب مرفوع بالضمة. البناء ثبات آخر الكلمة على حالة في أحوالها، والإعراب تغيره بحسب العوامل أو موقع الكلمة.","prompt":"أي اسم مبني في «هذا كتابٌ»؟","correct":"هذا","w1":"كتاب","w2":"الجملة كلها","w3":"علامة الضمة","practice":"أنشئ ثماني جمل تستعمل أسماء إشارة وأسماء معربة، ثم حدد البناء والإعراب والمحل."},{"n":8,"skill":"علامات الإعراب الأصلية والفرعية","passage":"«جاء الطالبُ» فاعله مرفوع بالضمة، و«رأيتُ الطالبَ» مفعوله منصوب بالفتحة، و«مررتُ بالطالبِ» اسم مجرور بالكسرة. وقد تنوب علامات فرعية مثل الألف في رفع المثنى وفق الشروط.","prompt":"ما علامة رفع المثنى في «جاء الطالبان»؟","correct":"الألف","w1":"الضمة الظاهرة","w2":"الياء","w3":"الكسرة","practice":"أعرب جملًا فيها مفرد ومثنى وجمع مذكر سالم، وحدد العلامة الأصلية أو الفرعية وسببها."},{"n":9,"skill":"الميزان الصرفي والزيادة","passage":"«كتب» على وزن «فعل»، و«كاتب» على «فاعل» لزيادة الألف، و«مكتوب» على «مفعول». يقابل الميزان الحروف الأصلية بالفاء والعين واللام، وتُثبت الزيادة في مكانها من الميزان.","prompt":"ما وزن «مكتوب»؟","correct":"مفعول","w1":"فاعل","w2":"فعول","w3":"افتعل","practice":"زن عشرة ألفاظ من جذور مختلفة، واكتب الجذر والحروف الزائدة مع مراجعة شكل الحركة."},{"n":10,"skill":"المصدر المجرد والمزيد","passage":"«كتابة» مصدر للفعل الثلاثي «كتب»، أما «تعليم» فهو مصدر «علّم» المزيد بالتضعيف، و«استخراج» مصدر «استخرج». تظهر أوزان المصدر حسب البنية الصرفية، مع مصادر سماعية للثلاثي.","prompt":"أي كلمة مصدر الفعل «استخرج»؟","correct":"استخراج","w1":"مستخرج","w2":"يستخرج","w3":"خارج","practice":"اشتق مصادر عشرة أفعال ثم صنفها إلى مصادر سماعية أو قياسية بحسب ما تسمح به القاعدة."},{"n":11,"skill":"الإسناد الخبري ودرجة التوكيد","passage":"«المراجعةُ مفيدةٌ» خبر ابتدائي يخلو من أدوات التوكيد، و«إنَّ المراجعةَ مفيدةٌ» خبر مؤكد. يختار المتكلم الصيغة تبعًا لحال المخاطب والغرض. لا يعني استخدام المؤكد أن المضمون صحيح دون دليل.","prompt":"أي جملة تتضمن أداة توكيد؟","correct":"إن المراجعة مفيدة","w1":"المراجعة مفيدة","w2":"هل المراجعة مفيدة؟","w3":"راجع الدرس","practice":"اكتب ثلاث صيغ لخبر واحد تناسب من لا يعرف المعلومة ومن يشك فيها ومن ينكرها، مع تحليل الأدوات."},{"n":12,"skill":"المجاز العقلي في إسناد الفعل","passage":"في قول مستقل «بنى المديرُ المدرسةَ» مع معرفة أن البنّائين هم من شيدوها فعليًا، يمكن فهم إسناد البناء إلى المدير لإشرافه أو سببيته، وهو من المجاز العقلي بحسب القرينة. أما إذا بنى المدير بنفسه فلا يلزم المجاز.","prompt":"ما أساس المجاز العقلي في المثال المفترض؟","correct":"إسناد البناء إلى المشرف بدل المنفذين مع قرينة","w1":"وجود مدرسة","w2":"اختيار لفظ المدير","w3":"فعل ماض فقط","practice":"كوّن ثلاثة أمثلة على إسناد مجازي صحيح للفعل مع قرينة تبين العلاقة، وفرّق بينها وبين الاستعارة."},{"n":13,"skill":"النكرة والمعرفة وأنواع المعارف","passage":"«كتابٌ» نكرة غير معينة، و«الكتابُ» معرفة بأل، و«هذا» اسم إشارة من المعارف، و«محمد» علم من المعارف. تختلف وسائل التعريف بين الضمير والعلم واسم الإشارة والاسم الموصول والمعرّف بأل والمضاف إلى معرفة.","prompt":"أي كلمة معرفة بأل؟","correct":"الكتاب","w1":"كتاب","w2":"قلم","w3":"صفحة","practice":"اكتب فقرة من خمس جمل واستخرج منها أربع نكرات وست معارف متنوعة، ثم حدد طريقة التعريف."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=10
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027' AND cu.id='4611ec73-1e1a-4571-9c51-05d7c901c83f'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.title='نحو 111 — النحو والصرف والبلاغة' AND u.semester=1 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF char_length(coalesce(target_content,''))<350 THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف الثامن، الفصل الأول. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.'||E'\n\n'||'المدخل السابق المحفوظ: '||coalesce(target_content,''),
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف الثامن%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_RELIGIOUS_G10_T1_NAHW111_ORIGINAL_20261008','notOfficialBook',true,'ocrReview','pending','options',CASE (r.n % 4) WHEN 0 THEN jsonb_build_array(r.correct,r.w1,r.w2,r.w3) WHEN 1 THEN jsonb_build_array(r.w1,r.correct,r.w2,r.w3) WHEN 2 THEN jsonb_build_array(r.w1,r.w2,r.correct,r.w3) ELSE jsonb_build_array(r.w1,r.w2,r.w3,r.correct) END),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_RELIGIOUS_G10_T1_NAHW111_ORIGINAL_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_RELIGIOUS_G10_T1_NAHW111_ORIGINAL_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_RELIGIOUS_G10_T1_NAHW111_ORIGINAL_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;